INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('874cfe78-646e-588a-9824-19e362939244','TEXT','A passage 1','The mangrove restoration project at the regional agricultural show began with a simple observation. Tahlia noticed that the first plan treated several small problems as though they were the same problem. The team changed its method: they recorded each issue, tested one change at a time and compared the new result with the original notes.
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('e8adbc8b-669c-5ff5-a284-a163fea1cdad', 'MULTIPLE_CHOICE', 9, 'READING', 'Main idea and purpose', 4, NULL, NULL, 'Which statement best expresses the main idea?', '[{"label":"A","text":"A competition is cancelled without explanation."},{"label":"B","text":"The text explains how people respond to a practical problem and use evidence to guide the next step."},{"label":"C","text":"A new product is advertised to the public."},{"label":"D","text":"A character solves a problem instantly."}]'::jsonb, '{"value":"B"}'::jsonb, 'The answer summarises the central problem and response.', 'PUBLISHED', NULL, 'ADVANCED', 'EASY', 1, 'COMPREHENSION', 'Reading for meaning', NULL, '874cfe78-646e-588a-9824-19e362939244', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','e8adbc8b-669c-5ff5-a284-a163fea1cdad',1,'b93dadbe-1a6b-5405-929d-3a50280c439f','0b6f37f4-b028-5bd4-bb9a-b2001628237f') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('18f95f89-9581-5fd3-b23f-3dbad1edfde6', 'MULTIPLE_CHOICE', 9, 'READING', 'Locating information', 5, NULL, NULL, 'Which detail best supports the main idea?', '[{"label":"A","text":"The project is held outdoors."},{"label":"B","text":"The group uses a timetable."},{"label":"C","text":"The group changes its approach after comparing information with what is happening."},{"label":"D","text":"The volunteers arrive in the afternoon."}]'::jsonb, '{"value":"C"}'::jsonb, 'This detail directly describes the change that drives the text.', 'PUBLISHED', NULL, 'ADVANCED', 'EASY', 1, 'COMPREHENSION', 'Reading for meaning', NULL, '874cfe78-646e-588a-9824-19e362939244', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','18f95f89-9581-5fd3-b23f-3dbad1edfde6',2,'b93dadbe-1a6b-5405-929d-3a50280c439f','0b6f37f4-b028-5bd4-bb9a-b2001628237f') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('029281b3-93d3-5d54-9bf0-ac897d322a0b', 'MULTIPLE_CHOICE', 9, 'READING', 'Inference', 4, NULL, NULL, 'What can the reader infer about the group''s approach?', '[{"label":"A","text":"They never compare results."},{"label":"B","text":"The people involved value testing an idea before committing to it."},{"label":"C","text":"They believe the first idea is always best."},{"label":"D","text":"They avoid all decisions."}]'::jsonb, '{"value":"B"}'::jsonb, 'Their actions show a preference for evidence and testing.', 'PUBLISHED', NULL, 'ADVANCED', 'EASY', 1, 'ANALYSIS', 'Reading for meaning', NULL, '874cfe78-646e-588a-9824-19e362939244', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','029281b3-93d3-5d54-9bf0-ac897d322a0b',3,'b93dadbe-1a6b-5405-929d-3a50280c439f','0b6f37f4-b028-5bd4-bb9a-b2001628237f') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('3fc97606-25e7-5b56-a5c4-7cd9ddab0c0d', 'MULTIPLE_CHOICE', 9, 'READING', 'Vocabulary in context', 5, NULL, NULL, 'In the passage, “trial” is closest in meaning to which phrase?', '[{"label":"A","text":"a test of an idea"},{"label":"B","text":"an unrelated opinion"},{"label":"C","text":"a rule with no exceptions"},{"label":"D","text":"a final result that cannot change"}]'::jsonb, '{"value":"A"}'::jsonb, 'The surrounding context supports the meaning “a test of an idea.”', 'PUBLISHED', NULL, 'ADVANCED', 'EASY', 1, 'COMPREHENSION', 'Reading for meaning', NULL, '874cfe78-646e-588a-9824-19e362939244', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','3fc97606-25e7-5b56-a5c4-7cd9ddab0c0d',4,'b93dadbe-1a6b-5405-929d-3a50280c439f','0b6f37f4-b028-5bd4-bb9a-b2001628237f') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('28ca8884-533e-5a1f-b607-0e7bad5017b1', 'MULTIPLE_CHOICE', 9, 'READING', 'Text structure', 4, NULL, NULL, 'How is the text mainly organised?', '[{"label":"A","text":"It gives instructions with no explanation."},{"label":"B","text":"It lists unrelated facts only."},{"label":"C","text":"It presents a problem but gives no response."},{"label":"D","text":"It introduces a situation, describes a response and explains what was learned."}]'::jsonb, '{"value":"D"}'::jsonb, 'The text moves from situation to response to implication.', 'PUBLISHED', NULL, 'ADVANCED', 'EASY', 1, 'ANALYSIS', 'Reading for meaning', NULL, '874cfe78-646e-588a-9824-19e362939244', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','28ca8884-533e-5a1f-b607-0e7bad5017b1',5,'b93dadbe-1a6b-5405-929d-3a50280c439f','0b6f37f4-b028-5bd4-bb9a-b2001628237f') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('94e3193b-534b-5b33-bd50-364f83d3afa9', 'MULTIPLE_CHOICE', 9, 'READING', 'Evidence and support', 5, NULL, NULL, 'Which statement is the strongest evidence for the claim that the team used evidence?', '[{"label":"A","text":"The passage explains that the team compared new results with earlier notes."},{"label":"B","text":"The passage mentions an afternoon."},{"label":"C","text":"The setting is a community site."},{"label":"D","text":"A person''s name is included."}]'::jsonb, '{"value":"A"}'::jsonb, 'The selected detail directly describes comparison of results.', 'PUBLISHED', NULL, 'ADVANCED', 'EASY', 1, 'ANALYSIS', 'Reading for meaning', NULL, '874cfe78-646e-588a-9824-19e362939244', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','94e3193b-534b-5b33-bd50-364f83d3afa9',6,'b93dadbe-1a6b-5405-929d-3a50280c439f','0b6f37f4-b028-5bd4-bb9a-b2001628237f') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('37db8f0b-883e-583e-8bc9-d75d9a0d1cf6', 'MULTIPLE_CHOICE', 9, 'READING', 'Author purpose', 4, NULL, NULL, 'What is the author''s main purpose?', '[{"label":"A","text":"To explain an approach to solving a practical problem and why it is useful."},{"label":"B","text":"To provide cooking directions."},{"label":"C","text":"To tell a joke."},{"label":"D","text":"To advertise a service."}]'::jsonb, '{"value":"A"}'::jsonb, 'The text explains an approach and its implications.', 'PUBLISHED', NULL, 'ADVANCED', 'EASY', 1, 'ANALYSIS', 'Reading for meaning', NULL, '874cfe78-646e-588a-9824-19e362939244', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','37db8f0b-883e-583e-8bc9-d75d9a0d1cf6',7,'b93dadbe-1a6b-5405-929d-3a50280c439f','0b6f37f4-b028-5bd4-bb9a-b2001628237f') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('cbb59858-78b4-5e93-8a39-579af7319253', 'MULTIPLE_CHOICE', 9, 'READING', 'Evaluation', 5, NULL, NULL, 'Which evaluation of the author''s viewpoint is best supported?', '[{"label":"A","text":"The author rejects all trialling."},{"label":"B","text":"The author supports careful testing rather than relying on an untested first idea."},{"label":"C","text":"The author prefers decisions made without evidence."},{"label":"D","text":"The author says results never matter."}]'::jsonb, '{"value":"B"}'::jsonb, 'The text consistently values testing and evidence.', 'PUBLISHED', NULL, 'ADVANCED', 'EASY', 1, 'ANALYSIS', 'Reading for meaning', NULL, '874cfe78-646e-588a-9824-19e362939244', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','cbb59858-78b4-5e93-8a39-579af7319253',8,'b93dadbe-1a6b-5405-929d-3a50280c439f','0b6f37f4-b028-5bd4-bb9a-b2001628237f') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('2b300387-c7f8-5718-81f1-894e4f65f1a2','TEXT','A passage 2','At the school house competition, the night market volunteers project divided volunteers into small teams. One team wanted to begin immediately, while another argued for a short planning session. Callum listened to both sides and suggested a trial that would reveal which approach worked best. By the end of the afternoon, the group had discovered that the best solution was not the fastest idea or the most complicated one. It was the idea that made the next decision easier.',NULL,NULL,NULL,9,'READING','PUBLISHED',NULL);
