INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('2d8c57fb-3fd7-5dc1-9f7f-8d8acd59a6ff', 'MULTIPLE_CHOICE', 9, 'READING', 'Author purpose', 4, NULL, NULL, 'What is the author''s main purpose?', '[{"label":"A","text":"To explain an approach to solving a practical problem and why it is useful."},{"label":"B","text":"To provide cooking directions."},{"label":"C","text":"To tell a joke."},{"label":"D","text":"To advertise a service."}]'::jsonb, '{"value":"A"}'::jsonb, 'The text explains an approach and its implications.', 'PUBLISHED', NULL, 'ADVANCED', 'EASY', 1, 'ANALYSIS', 'Reading for meaning', NULL, '2b300387-c7f8-5718-81f1-894e4f65f1a2', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','2d8c57fb-3fd7-5dc1-9f7f-8d8acd59a6ff',15,'b93dadbe-1a6b-5405-929d-3a50280c439f','0b6f37f4-b028-5bd4-bb9a-b2001628237f') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('7cc9d57b-4456-5da2-8aa4-3d501c736415', 'MULTIPLE_CHOICE', 9, 'READING', 'Evaluation', 5, NULL, NULL, 'Which evaluation of the author''s viewpoint is best supported?', '[{"label":"A","text":"The author rejects all trialling."},{"label":"B","text":"The author supports careful testing rather than relying on an untested first idea."},{"label":"C","text":"The author prefers decisions made without evidence."},{"label":"D","text":"The author says results never matter."}]'::jsonb, '{"value":"B"}'::jsonb, 'The text consistently values testing and evidence.', 'PUBLISHED', NULL, 'ADVANCED', 'EASY', 1, 'ANALYSIS', 'Reading for meaning', NULL, '2b300387-c7f8-5718-81f1-894e4f65f1a2', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','7cc9d57b-4456-5da2-8aa4-3d501c736415',16,'b93dadbe-1a6b-5405-929d-3a50280c439f','0b6f37f4-b028-5bd4-bb9a-b2001628237f') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('8ca5e3ab-66ff-52e9-a0fe-262886421d30','TEXT','B passage 1','At the school house competition, the stormwater gardens project divided volunteers into small teams. One team wanted to begin immediately, while another argued for a short planning session. Mia listened to both sides and suggested a trial that would reveal which approach worked best. By the end of the afternoon, the group had discovered that the best solution was not the fastest idea or the most complicated one. It was the idea that made the next decision easier.',NULL,NULL,NULL,9,'READING','PUBLISHED',NULL);
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('69e1f792-1b01-5d4a-bf39-5b0a94662f4f', 'MULTIPLE_CHOICE', 9, 'READING', 'Main idea and purpose', 4, NULL, NULL, 'Which statement best expresses the main idea?', '[{"label":"A","text":"A competition is cancelled without explanation."},{"label":"B","text":"The text explains how people respond to a practical problem and use evidence to guide the next step."},{"label":"C","text":"A new product is advertised to the public."},{"label":"D","text":"A character solves a problem instantly."}]'::jsonb, '{"value":"B"}'::jsonb, 'The answer summarises the central problem and response.', 'PUBLISHED', NULL, 'ADVANCED', 'EASY', 1, 'COMPREHENSION', 'Reading for meaning', NULL, '8ca5e3ab-66ff-52e9-a0fe-262886421d30', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','69e1f792-1b01-5d4a-bf39-5b0a94662f4f',17,'b93dadbe-1a6b-5405-929d-3a50280c439f','0dca2ff2-eabb-562e-955c-012f1d64d5e0') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('fcfd95e1-3a49-5668-9aa5-8ab2ec2ffa16', 'MULTIPLE_CHOICE', 9, 'READING', 'Locating information', 5, NULL, NULL, 'Which detail best supports the main idea?', '[{"label":"A","text":"The project is held outdoors."},{"label":"B","text":"The group uses a timetable."},{"label":"C","text":"The group changes its approach after comparing information with what is happening."},{"label":"D","text":"The volunteers arrive in the afternoon."}]'::jsonb, '{"value":"C"}'::jsonb, 'This detail directly describes the change that drives the text.', 'PUBLISHED', NULL, 'ADVANCED', 'EASY', 1, 'COMPREHENSION', 'Reading for meaning', NULL, '8ca5e3ab-66ff-52e9-a0fe-262886421d30', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','fcfd95e1-3a49-5668-9aa5-8ab2ec2ffa16',18,'b93dadbe-1a6b-5405-929d-3a50280c439f','0dca2ff2-eabb-562e-955c-012f1d64d5e0') ON CONFLICT (exam_id,question_id) DO NOTHING;
