INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('3860480b-b614-5524-9297-ce9537ce1265','TEXT','B passage 2','Some people in the recycling station support expanding the young inventor challenge project, while others want to see more evidence first. Supporters point to improved participation and clearer results from the trial. Critics agree the early signs are useful but argue that a larger rollout should happen in stages. A practical compromise would keep the trial running long enough to measure whether the improvement continues before major resources are committed.',NULL,NULL,NULL,9,'READING','PUBLISHED',NULL);
