INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('3a17ddad-fe60-5dcd-88ea-3f4044ef3a71', 'MULTIPLE_CHOICE', 9, 'READING', 'Author purpose', 4, NULL, NULL, 'What is the author''s main purpose?', '[{"label":"A","text":"To explain an approach to solving a practical problem and why it is useful."},{"label":"B","text":"To provide cooking directions."},{"label":"C","text":"To tell a joke."},{"label":"D","text":"To advertise a service."}]'::jsonb, '{"value":"A"}'::jsonb, 'The text explains an approach and its implications.', 'PUBLISHED', NULL, 'ADVANCED', 'EASY', 1, 'ANALYSIS', 'Reading for meaning', NULL, '3860480b-b614-5524-9297-ce9537ce1265', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','3a17ddad-fe60-5dcd-88ea-3f4044ef3a71',31,'b93dadbe-1a6b-5405-929d-3a50280c439f','0dca2ff2-eabb-562e-955c-012f1d64d5e0') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('533f5071-cbbe-532f-a013-2c3cbad43bbb', 'MULTIPLE_CHOICE', 9, 'READING', 'Evaluation', 5, NULL, NULL, 'Which evaluation of the author''s viewpoint is best supported?', '[{"label":"A","text":"The author rejects all trialling."},{"label":"B","text":"The author supports careful testing rather than relying on an untested first idea."},{"label":"C","text":"The author prefers decisions made without evidence."},{"label":"D","text":"The author says results never matter."}]'::jsonb, '{"value":"B"}'::jsonb, 'The text consistently values testing and evidence.', 'PUBLISHED', NULL, 'ADVANCED', 'EASY', 1, 'ANALYSIS', 'Reading for meaning', NULL, '3860480b-b614-5524-9297-ce9537ce1265', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','533f5071-cbbe-532f-a013-2c3cbad43bbb',32,'b93dadbe-1a6b-5405-929d-3a50280c439f','0dca2ff2-eabb-562e-955c-012f1d64d5e0') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('4d284910-a4a6-592d-980c-70eca7008ec0','TEXT','B_LATE passage 1','Some people in the recycling station support expanding the river bird counts project, while others want to see more evidence first. Supporters point to improved participation and clearer results from the trial. Critics agree the early signs are useful but argue that a larger rollout should happen in stages. A practical compromise would keep the trial running long enough to measure whether the improvement continues before major resources are committed.',NULL,NULL,NULL,9,'READING','PUBLISHED',NULL);
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('6bdddb79-205f-5563-8623-1e2e3e157592', 'MULTIPLE_CHOICE', 9, 'READING', 'Main idea and purpose', 5, NULL, NULL, 'Which statement best expresses the main idea?', '[{"label":"A","text":"A competition is cancelled without explanation."},{"label":"B","text":"The text explains how people respond to a practical problem and use evidence to guide the next step."},{"label":"C","text":"A new product is advertised to the public."},{"label":"D","text":"A character solves a problem instantly."}]'::jsonb, '{"value":"B"}'::jsonb, 'The answer summarises the central problem and response.', 'PUBLISHED', NULL, 'ADVANCED', 'EASY', 1, 'COMPREHENSION', 'Reading for meaning', NULL, '4d284910-a4a6-592d-980c-70eca7008ec0', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','6bdddb79-205f-5563-8623-1e2e3e157592',33,'b93dadbe-1a6b-5405-929d-3a50280c439f','21e420d3-f4ff-537a-b824-34379ef3f820') ON CONFLICT (exam_id,question_id) DO NOTHING;
