INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('d01bce1d-dfb8-5b01-944d-fcb2d8497aed', 'MULTIPLE_CHOICE', 9, 'READING', 'Author purpose', 5, NULL, NULL, 'What is the author''s main purpose?', '[{"label":"A","text":"To explain an approach to solving a practical problem and why it is useful."},{"label":"B","text":"To provide cooking directions."},{"label":"C","text":"To tell a joke."},{"label":"D","text":"To advertise a service."}]'::jsonb, '{"value":"A"}'::jsonb, 'The text explains an approach and its implications.', 'PUBLISHED', NULL, 'ADVANCED', 'EASY', 1, 'ANALYSIS', 'Reading for meaning', NULL, 'a4e26563-6d53-5a08-a5ec-9e032c501a68', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','d01bce1d-dfb8-5b01-944d-fcb2d8497aed',47,'b93dadbe-1a6b-5405-929d-3a50280c439f','21e420d3-f4ff-537a-b824-34379ef3f820') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('c428e9af-c42e-517d-af9c-3c2b77fa00a8', 'MULTIPLE_CHOICE', 9, 'READING', 'Evaluation', 6, NULL, NULL, 'Which evaluation of the author''s viewpoint is best supported?', '[{"label":"A","text":"The author rejects all trialling."},{"label":"B","text":"The author supports careful testing rather than relying on an untested first idea."},{"label":"C","text":"The author prefers decisions made without evidence."},{"label":"D","text":"The author says results never matter."}]'::jsonb, '{"value":"B"}'::jsonb, 'The text consistently values testing and evidence.', 'PUBLISHED', NULL, 'ADVANCED', 'MEDIUM', 1, 'ANALYSIS', 'Reading for meaning', NULL, 'a4e26563-6d53-5a08-a5ec-9e032c501a68', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','c428e9af-c42e-517d-af9c-3c2b77fa00a8',48,'b93dadbe-1a6b-5405-929d-3a50280c439f','21e420d3-f4ff-537a-b824-34379ef3f820') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('1fd4868d-35e4-5ac9-948b-1b66377269d5','TEXT','C passage 1','The coastal weather station project at the public park upgrade began with a simple observation. Sienna noticed that the first plan treated several small problems as though they were the same problem. The team changed its method: they recorded each issue, tested one change at a time and compared the new result with the original notes.
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('2837ffc9-5826-5b37-a536-527c3571ee36', 'MULTIPLE_CHOICE', 9, 'READING', 'Main idea and purpose', 5, NULL, NULL, 'Which statement best expresses the main idea?', '[{"label":"A","text":"A competition is cancelled without explanation."},{"label":"B","text":"The text explains how people respond to a practical problem and use evidence to guide the next step."},{"label":"C","text":"A new product is advertised to the public."},{"label":"D","text":"A character solves a problem instantly."}]'::jsonb, '{"value":"B"}'::jsonb, 'The answer summarises the central problem and response.', 'PUBLISHED', NULL, 'ADVANCED', 'EASY', 1, 'COMPREHENSION', 'Reading for meaning', NULL, '1fd4868d-35e4-5ac9-948b-1b66377269d5', TRUE, NULL) ;
