INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('fd6199ec-c009-58a6-a0a3-d45b63e72e3c','TEXT','C passage 2','At the junior rowing club, the community bicycle scheme project divided volunteers into small teams. One team wanted to begin immediately, while another argued for a short planning session. Noah listened to both sides and suggested a trial that would reveal which approach worked best. By the end of the afternoon, the group had discovered that the best solution was not the fastest idea or the most complicated one. It was the idea that made the next decision easier.',NULL,NULL,NULL,9,'READING','PUBLISHED',NULL);
