INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('60b3b6ab-0361-5faf-b43c-46b7b21e6637', 'MULTIPLE_CHOICE', 9, 'READING', 'Author purpose', 5, NULL, NULL, 'What is the author''s main purpose?', '[{"label":"A","text":"To explain an approach to solving a practical problem and why it is useful."},{"label":"B","text":"To provide cooking directions."},{"label":"C","text":"To tell a joke."},{"label":"D","text":"To advertise a service."}]'::jsonb, '{"value":"A"}'::jsonb, 'The text explains an approach and its implications.', 'PUBLISHED', NULL, 'ADVANCED', 'EASY', 1, 'ANALYSIS', 'Reading for meaning', NULL, 'fd6199ec-c009-58a6-a0a3-d45b63e72e3c', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','60b3b6ab-0361-5faf-b43c-46b7b21e6637',63,'b93dadbe-1a6b-5405-929d-3a50280c439f','105a08f7-bbd2-5b86-b748-fdac54242255') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('74ca5abb-fd26-5744-9646-55c1d697e72b', 'MULTIPLE_CHOICE', 9, 'READING', 'Evaluation', 6, NULL, NULL, 'Which evaluation of the author''s viewpoint is best supported?', '[{"label":"A","text":"The author rejects all trialling."},{"label":"B","text":"The author supports careful testing rather than relying on an untested first idea."},{"label":"C","text":"The author prefers decisions made without evidence."},{"label":"D","text":"The author says results never matter."}]'::jsonb, '{"value":"B"}'::jsonb, 'The text consistently values testing and evidence.', 'PUBLISHED', NULL, 'ADVANCED', 'MEDIUM', 1, 'ANALYSIS', 'Reading for meaning', NULL, 'fd6199ec-c009-58a6-a0a3-d45b63e72e3c', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','74ca5abb-fd26-5744-9646-55c1d697e72b',64,'b93dadbe-1a6b-5405-929d-3a50280c439f','105a08f7-bbd2-5b86-b748-fdac54242255') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('686db91a-dbb6-5e6c-b678-28a1a9814697','TEXT','C_EARLY passage 1','At the junior rowing club, the wetland boardwalk project divided volunteers into small teams. One team wanted to begin immediately, while another argued for a short planning session. Tahlia listened to both sides and suggested a trial that would reveal which approach worked best. By the end of the afternoon, the group had discovered that the best solution was not the fastest idea or the most complicated one. It was the idea that made the next decision easier.',NULL,NULL,NULL,9,'READING','PUBLISHED',NULL);
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('f38330e2-67b5-5c74-ab2b-1884c12f7f5e', 'MULTIPLE_CHOICE', 9, 'READING', 'Main idea and purpose', 6, NULL, NULL, 'Which statement best expresses the main idea?', '[{"label":"A","text":"A competition is cancelled without explanation."},{"label":"B","text":"The text explains how people respond to a practical problem and use evidence to guide the next step."},{"label":"C","text":"A new product is advertised to the public."},{"label":"D","text":"A character solves a problem instantly."}]'::jsonb, '{"value":"B"}'::jsonb, 'The answer summarises the central problem and response.', 'PUBLISHED', NULL, 'ADVANCED', 'MEDIUM', 1, 'COMPREHENSION', 'Reading for meaning', NULL, '686db91a-dbb6-5e6c-b678-28a1a9814697', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','f38330e2-67b5-5c74-ab2b-1884c12f7f5e',65,'b93dadbe-1a6b-5405-929d-3a50280c439f','1ccdf832-9b74-5651-8442-30ceef467070') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('166a2a5d-339d-537a-a0a6-83818f966c7d', 'MULTIPLE_CHOICE', 9, 'READING', 'Locating information', 7, NULL, NULL, 'Which detail best supports the main idea?', '[{"label":"A","text":"The project is held outdoors."},{"label":"B","text":"The group uses a timetable."},{"label":"C","text":"The group changes its approach after comparing information with what is happening."},{"label":"D","text":"The volunteers arrive in the afternoon."}]'::jsonb, '{"value":"C"}'::jsonb, 'This detail directly describes the change that drives the text.', 'PUBLISHED', NULL, 'ADVANCED', 'HARD', 1, 'COMPREHENSION', 'Reading for meaning', NULL, '686db91a-dbb6-5e6c-b678-28a1a9814697', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','166a2a5d-339d-537a-a0a6-83818f966c7d',66,'b93dadbe-1a6b-5405-929d-3a50280c439f','1ccdf832-9b74-5651-8442-30ceef467070') ON CONFLICT (exam_id,question_id) DO NOTHING;
