INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('1e6f6edb-bc34-58a3-8a51-644e476a967e', 'MULTIPLE_CHOICE', 9, 'READING', 'Author purpose', 6, NULL, NULL, 'What is the author''s main purpose?', '[{"label":"A","text":"To explain an approach to solving a practical problem and why it is useful."},{"label":"B","text":"To provide cooking directions."},{"label":"C","text":"To tell a joke."},{"label":"D","text":"To advertise a service."}]'::jsonb, '{"value":"A"}'::jsonb, 'The text explains an approach and its implications.', 'PUBLISHED', NULL, 'ADVANCED', 'MEDIUM', 1, 'ANALYSIS', 'Reading for meaning', NULL, 'ea0c5d23-1f29-5e09-825b-49b3674acac4', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','1e6f6edb-bc34-58a3-8a51-644e476a967e',79,'b93dadbe-1a6b-5405-929d-3a50280c439f','1ccdf832-9b74-5651-8442-30ceef467070') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('7b57c0d1-e4ad-5240-aa53-6a1acbd38951', 'MULTIPLE_CHOICE', 9, 'READING', 'Evaluation', 7, NULL, NULL, 'Which evaluation of the author''s viewpoint is best supported?', '[{"label":"A","text":"The author rejects all trialling."},{"label":"B","text":"The author supports careful testing rather than relying on an untested first idea."},{"label":"C","text":"The author prefers decisions made without evidence."},{"label":"D","text":"The author says results never matter."}]'::jsonb, '{"value":"B"}'::jsonb, 'The text consistently values testing and evidence.', 'PUBLISHED', NULL, 'ADVANCED', 'HARD', 1, 'ANALYSIS', 'Reading for meaning', NULL, 'ea0c5d23-1f29-5e09-825b-49b3674acac4', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','7b57c0d1-e4ad-5240-aa53-6a1acbd38951',80,'b93dadbe-1a6b-5405-929d-3a50280c439f','1ccdf832-9b74-5651-8442-30ceef467070') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('c49c3182-a91a-51bd-b9b9-0b928893b5d9','TEXT','D passage 1','Some people in the coastal monitoring team support expanding the local theatre rehearsal project, while others want to see more evidence first. Supporters point to improved participation and clearer results from the trial. Critics agree the early signs are useful but argue that a larger rollout should happen in stages. A practical compromise would keep the trial running long enough to measure whether the improvement continues before major resources are committed.',NULL,NULL,NULL,9,'READING','PUBLISHED',NULL);
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('b7788ead-7690-50b9-9939-108aa6136ddf', 'MULTIPLE_CHOICE', 9, 'READING', 'Main idea and purpose', 6, NULL, NULL, 'Which statement best expresses the main idea?', '[{"label":"A","text":"A competition is cancelled without explanation."},{"label":"B","text":"The text explains how people respond to a practical problem and use evidence to guide the next step."},{"label":"C","text":"A new product is advertised to the public."},{"label":"D","text":"A character solves a problem instantly."}]'::jsonb, '{"value":"B"}'::jsonb, 'The answer summarises the central problem and response.', 'PUBLISHED', NULL, 'ADVANCED', 'MEDIUM', 1, 'COMPREHENSION', 'Reading for meaning', NULL, 'c49c3182-a91a-51bd-b9b9-0b928893b5d9', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','b7788ead-7690-50b9-9939-108aa6136ddf',81,'b93dadbe-1a6b-5405-929d-3a50280c439f','5757ce97-dd33-51b6-8080-d2104a7e9ca0') ON CONFLICT (exam_id,question_id) DO NOTHING;
