INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('df4812db-7c19-5e6f-9248-42929425bac5','TEXT','D passage 2','The solar-powered bus stop project at the school excursion planner began with a simple observation. Mia noticed that the first plan treated several small problems as though they were the same problem. The team changed its method: they recorded each issue, tested one change at a time and compared the new result with the original notes.
