INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('8f783295-2700-575d-ad1b-fe6a160537f7', 'MULTIPLE_CHOICE', 9, 'READING', 'Author purpose', 6, NULL, NULL, 'What is the author''s main purpose?', '[{"label":"A","text":"To explain an approach to solving a practical problem and why it is useful."},{"label":"B","text":"To provide cooking directions."},{"label":"C","text":"To tell a joke."},{"label":"D","text":"To advertise a service."}]'::jsonb, '{"value":"A"}'::jsonb, 'The text explains an approach and its implications.', 'PUBLISHED', NULL, 'ADVANCED', 'MEDIUM', 1, 'ANALYSIS', 'Reading for meaning', NULL, 'df4812db-7c19-5e6f-9248-42929425bac5', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','8f783295-2700-575d-ad1b-fe6a160537f7',95,'b93dadbe-1a6b-5405-929d-3a50280c439f','5757ce97-dd33-51b6-8080-d2104a7e9ca0') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('a0ffd216-fbc0-5242-8255-3ae70d36cdf2', 'MULTIPLE_CHOICE', 9, 'READING', 'Evaluation', 7, NULL, NULL, 'Which evaluation of the author''s viewpoint is best supported?', '[{"label":"A","text":"The author rejects all trialling."},{"label":"B","text":"The author supports careful testing rather than relying on an untested first idea."},{"label":"C","text":"The author prefers decisions made without evidence."},{"label":"D","text":"The author says results never matter."}]'::jsonb, '{"value":"B"}'::jsonb, 'The text consistently values testing and evidence.', 'PUBLISHED', NULL, 'ADVANCED', 'HARD', 1, 'ANALYSIS', 'Reading for meaning', NULL, 'df4812db-7c19-5e6f-9248-42929425bac5', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','a0ffd216-fbc0-5242-8255-3ae70d36cdf2',96,'b93dadbe-1a6b-5405-929d-3a50280c439f','5757ce97-dd33-51b6-8080-d2104a7e9ca0') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('3e98a851-e471-51e5-9526-70dd14e26b69','TEXT','E passage 1','The mangrove restoration project at the school excursion planner began with a simple observation. Sienna noticed that the first plan treated several small problems as though they were the same problem. The team changed its method: they recorded each issue, tested one change at a time and compared the new result with the original notes.
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('f884335f-6e40-5978-b5f9-8b393054a527', 'MULTIPLE_CHOICE', 9, 'READING', 'Main idea and purpose', 7, NULL, NULL, 'Which statement best expresses the main idea?', '[{"label":"A","text":"A competition is cancelled without explanation."},{"label":"B","text":"The text explains how people respond to a practical problem and use evidence to guide the next step."},{"label":"C","text":"A new product is advertised to the public."},{"label":"D","text":"A character solves a problem instantly."}]'::jsonb, '{"value":"B"}'::jsonb, 'The answer summarises the central problem and response.', 'PUBLISHED', NULL, 'ADVANCED', 'HARD', 1, 'COMPREHENSION', 'Reading for meaning', NULL, '3e98a851-e471-51e5-9526-70dd14e26b69', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','f884335f-6e40-5978-b5f9-8b393054a527',97,'b93dadbe-1a6b-5405-929d-3a50280c439f','f9f76fee-4977-56a5-804d-c8bbcf992c04') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('5ccc2deb-a79d-5f1e-bac0-a9161d97f2b1', 'MULTIPLE_CHOICE', 9, 'READING', 'Locating information', 8, NULL, NULL, 'Which detail best supports the main idea?', '[{"label":"A","text":"The project is held outdoors."},{"label":"B","text":"The group uses a timetable."},{"label":"C","text":"The group changes its approach after comparing information with what is happening."},{"label":"D","text":"The volunteers arrive in the afternoon."}]'::jsonb, '{"value":"C"}'::jsonb, 'This detail directly describes the change that drives the text.', 'PUBLISHED', NULL, 'ADVANCED', 'HARD', 1, 'COMPREHENSION', 'Reading for meaning', NULL, '3e98a851-e471-51e5-9526-70dd14e26b69', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','5ccc2deb-a79d-5f1e-bac0-a9161d97f2b1',98,'b93dadbe-1a6b-5405-929d-3a50280c439f','f9f76fee-4977-56a5-804d-c8bbcf992c04') ON CONFLICT (exam_id,question_id) DO NOTHING;
