INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('d94d1ae5-de14-599c-8b87-d05264a46de3', 'MULTIPLE_CHOICE', 9, 'READING', 'Author purpose', 7, NULL, NULL, 'What is the author''s main purpose?', '[{"label":"A","text":"To explain an approach to solving a practical problem and why it is useful."},{"label":"B","text":"To provide cooking directions."},{"label":"C","text":"To tell a joke."},{"label":"D","text":"To advertise a service."}]'::jsonb, '{"value":"A"}'::jsonb, 'The text explains an approach and its implications.', 'PUBLISHED', NULL, 'ADVANCED', 'HARD', 1, 'ANALYSIS', 'Reading for meaning', NULL, '89dea6c9-7226-52bf-baa5-7f9403eabae7', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','d94d1ae5-de14-599c-8b87-d05264a46de3',111,'b93dadbe-1a6b-5405-929d-3a50280c439f','f9f76fee-4977-56a5-804d-c8bbcf992c04') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('f5342d92-1d91-5b14-ac62-741348ed7c6b', 'MULTIPLE_CHOICE', 9, 'READING', 'Evaluation', 8, NULL, NULL, 'Which evaluation of the author''s viewpoint is best supported?', '[{"label":"A","text":"The author rejects all trialling."},{"label":"B","text":"The author supports careful testing rather than relying on an untested first idea."},{"label":"C","text":"The author prefers decisions made without evidence."},{"label":"D","text":"The author says results never matter."}]'::jsonb, '{"value":"B"}'::jsonb, 'The text consistently values testing and evidence.', 'PUBLISHED', NULL, 'ADVANCED', 'HARD', 1, 'ANALYSIS', 'Reading for meaning', NULL, '89dea6c9-7226-52bf-baa5-7f9403eabae7', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','f5342d92-1d91-5b14-ac62-741348ed7c6b',112,'b93dadbe-1a6b-5405-929d-3a50280c439f','f9f76fee-4977-56a5-804d-c8bbcf992c04') ON CONFLICT (exam_id,question_id) DO NOTHING;
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('9cf1ecdc-a2b0-513d-83ec-217f31bec63a','TEXT','F passage 1','At the community theatre group, the stormwater gardens project divided volunteers into small teams. One team wanted to begin immediately, while another argued for a short planning session. Mia listened to both sides and suggested a trial that would reveal which approach worked best. By the end of the afternoon, the group had discovered that the best solution was not the fastest idea or the most complicated one. It was the idea that made the next decision easier.',NULL,NULL,NULL,9,'READING','PUBLISHED',NULL);
INSERT INTO questions (id, question_type, year_level, domain, topic, difficulty_band, stimulus_text, stimulus_type, question_text, options, correct_answer, explanation, status, created_by, package_type, difficulty, marks, cognitive_skill, curriculum_strand, audio_url, stimulus_id, calculator_allowed, marking_rubric) VALUES ('d4724b66-f451-512c-a6e2-ba0e7bbf3774', 'MULTIPLE_CHOICE', 9, 'READING', 'Main idea and purpose', 7, NULL, NULL, 'Which statement best expresses the main idea?', '[{"label":"A","text":"A competition is cancelled without explanation."},{"label":"B","text":"The text explains how people respond to a practical problem and use evidence to guide the next step."},{"label":"C","text":"A new product is advertised to the public."},{"label":"D","text":"A character solves a problem instantly."}]'::jsonb, '{"value":"B"}'::jsonb, 'The answer summarises the central problem and response.', 'PUBLISHED', NULL, 'ADVANCED', 'HARD', 1, 'COMPREHENSION', 'Reading for meaning', NULL, '9cf1ecdc-a2b0-513d-83ec-217f31bec63a', TRUE, NULL) ;
INSERT INTO exam_questions (exam_id,question_id,question_order,section_id,testlet_id) VALUES ('08e03c0f-1275-5156-acd5-2f386a97e23d','d4724b66-f451-512c-a6e2-ba0e7bbf3774',113,'b93dadbe-1a6b-5405-929d-3a50280c439f','5ea50cab-7b30-54dd-b29b-b38f4feab2ba') ON CONFLICT (exam_id,question_id) DO NOTHING;
